function plotParse(src){
  var s=String(src||'').replace(/\s+/g,''), pos=0;
  var FUNCS={ sin:Math.sin, cos:Math.cos, tan:Math.tan, sqrt:Math.sqrt, abs:Math.abs, log:Math.log, exp:Math.exp, floor:Math.floor, atan:Math.atan };
  var CONSTS={ pi:Math.PI, e:Math.E };
  function peek(){ return s.charAt(pos); }
  function fail(msg){ throw new Error(msg+'（位置 '+pos+'）'); }
  function parseExpr(){
    var node=parseTerm();
    while(peek()==='+'||peek()==='-'){
      var op=s.charAt(pos++); var rhs=parseTerm();
      node=(function(l,r,o){ return function(x){ return o==='+' ? l(x)+r(x) : l(x)-r(x); }; })(node,rhs,op);
    }
    return node;
  }
  function parseTerm(){
    var node=parseUnary();
    while(peek()==='*'||peek()==='/'){
      var op=s.charAt(pos++); var rhs=parseUnary();
      node=(function(l,r,o){ return function(x){ return o==='*' ? l(x)*r(x) : l(x)/r(x); }; })(node,rhs,op);
    }
    return node;
  }
  function parseUnary(){
    if(peek()==='-'){ pos++; var inner=parseUnary(); return function(x){ return -inner(x); }; }
    return parsePow();
  }
  function parsePow(){
    var base=parseAtom();
    if(peek()==='^'){ pos++; var ex=parseUnary(); return function(x){ return Math.pow(base(x), ex(x)); }; }
    return base;
  }
  function parseAtom(){
    var c=peek();
    if(c==='('){ pos++; var inner=parseExpr(); if(peek()!==')') fail('缺少右括号'); pos++; return inner; }
    var mnum=/^\d+(\.\d+)?/.exec(s.slice(pos));
    if(mnum){ pos+=mnum[0].length; var v=Number(mnum[0]); return function(){ return v; }; }
    var mid=/^[a-z]+/.exec(s.slice(pos));
    if(mid){
      var id=mid[0]; pos+=id.length;
      if(id==='x') return function(x){ return x; };
      if(id in CONSTS){ var cv=CONSTS[id]; return function(){ return cv; }; }
      if(id in FUNCS){
        if(peek()!=='(') fail('函数 '+id+' 缺少参数');
        pos++; var arg=parseExpr();
        if(peek()!==')') fail('缺少右括号'); pos++;
        var fn=FUNCS[id]; return function(x){ return fn(arg(x)); };
      }
      fail('未知标识符 '+id);
    }
    fail('意外字符 "'+c+'"');
  }
  try{
    if(!s) return { error:'表达式为空', fn:null };
    var fn=parseExpr();
    if(pos<s.length) return { error:'解析在位置 '+pos+' 处中断', fn:null };
    fn(0); fn(1);
    return { error:null, fn:fn };
  }catch(e){ return { error:e.message, fn:null }; }
}
function plotSample(fn, xmin, xmax, count){
  count=count||200;
  var pts=[];
  for(var i=0;i<count;i++){
    var x=xmin+(xmax-xmin)*i/(count-1), y=fn(x);
    pts.push([x, isFinite(y)?y:null]);
  }
  return pts;
}
function plotSvg(fnResult, xmin, xmax){
  if(fnResult.error) return '';
  if(!(xmax>xmin)) return '';
  var W=640, H=360, PAD=34;
  var pts=plotSample(fnResult.fn, xmin, xmax, 240);
  var ys=pts.map(function(p){ return p[1]; }).filter(function(y){ return y!==null; });
  if(!ys.length) return '';
  var ymin=Math.min.apply(null,ys), ymax=Math.max.apply(null,ys);
  if(ymin===ymax){ ymin-=1; ymax+=1; }
  var span=ymax-ymin; ymin-=span*0.08; ymax+=span*0.08;
  function sx(x){ return PAD+(W-2*PAD)*(x-xmin)/(xmax-xmin); }
  function sy(y){ return H-PAD-(H-2*PAD)*(y-ymin)/(ymax-ymin); }
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  if(0>=ymin&&0<=ymax) s+='<line x1="'+PAD+'" y1="'+sy(0)+'" x2="'+(W-PAD)+'" y2="'+sy(0)+'" stroke="rgba(255,255,255,.2)"/>';
  if(0>=xmin&&0<=xmax) s+='<line x1="'+sx(0)+'" y1="'+PAD+'" x2="'+sx(0)+'" y2="'+(H-PAD)+'" stroke="rgba(255,255,255,.2)"/>';
  s+='<text x="'+PAD+'" y="'+(H-8)+'" font-family="system-ui,sans-serif" font-size="11" fill="#71717A">'+xmin+'</text>';
  s+='<text x="'+(W-PAD)+'" y="'+(H-8)+'" font-family="system-ui,sans-serif" font-size="11" fill="#71717A" text-anchor="end">'+xmax+'</text>';
  var d='', pen=false;
  for(var i=0;i<pts.length;i++){
    if(pts[i][1]===null){ pen=false; continue; }
    var X=sx(pts[i][0]), Y=sy(pts[i][1]);
    d+=(pen?'L':'M')+X.toFixed(1)+','+Y.toFixed(1); pen=true;
  }
  s+='<path d="'+d+'" fill="none" stroke="#5E6AD2" stroke-width="2"/>';
  return s+'</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { plotParse:plotParse, plotSample:plotSample, plotSvg:plotSvg };
}
if (typeof window !== 'undefined') {
  window.PlotForgePure = { plotParse:plotParse, plotSample:plotSample, plotSvg:plotSvg };
}
